-- Remove legacy anonymous authority only. Authenticated/service-role contracts are unchanged.
-- Reviewed against a read-only Production capture, 2026-09-24, client e6153d7.
-- The portable JSON guard includes exact ACLs, policies, column grants, constraints,
-- indexes, triggers, RPC bodies/signatures/owners/security/search_path and role inheritance.
-- No business DML, capability changes, global/default ACL changes, or function replacement.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '30s';
set local search_path = public, pg_catalog;
lock table public.production_rework_cycles in access exclusive mode;
do $guard$
declare actual jsonb;
begin
 select contract into actual from (
-- Portable catalog fingerprint: no OIDs, physical ordering, or business data.
-- rework is replaced only by the fixed literals core / rework by the verifier.
with target_tables as (
 select c.* from pg_class c join pg_namespace n on n.oid=c.relnamespace
 where n.nspname='public' and c.relname=any(case 'rework' when 'core' then
 array['manpower_entries','manpower_workers','manpower_tasks','manpower_reporting_groups']
 else array['production_rework_cycles'] end)
), target_functions as (
 select p.* from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and p.proname=any(case 'rework' when 'core' then
 array['delete_empty_manpower_reporting_group','set_manpower_updated_at','validate_manpower_product_category','has_app_capability']
 else array['create_production_rework','update_production_rework_status','save_production_rework_schedule_batch','save_production_rework_mixed_schedule_batch','touch_production_rework_cycle_updated_at','save_production_planning_schedule_batch'] end)
)
select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object(
 'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
 'acl',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a),
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by p.policyname),'[]'::jsonb) from pg_policies p where p.schemaname='public' and p.tablename=c.relname),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid),k.convalidated) order by k.conname),'[]'::jsonb) from pg_constraint k where k.conrelid=c.oid),
 'indexes',(select jsonb_agg(pg_get_indexdef(i.indexrelid) order by ic.relname) from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=c.oid),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) order by t.tgname),'[]'::jsonb) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)
 ) order by c.relname) from target_tables c),
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,
 'acl',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)
 ) order by p.oid::regprocedure::text) from target_functions p),
 'roles',(select jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolbypassrls) order by rolname) from pg_roles where rolname in ('anon','authenticated','service_role')),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),admin_option,inherit_option,set_option) order by pg_get_userbyid(roleid),pg_get_userbyid(member)),'[]'::jsonb) from pg_auth_members where member in ('anon'::regrole,'authenticated'::regrole,'service_role'::regrole))
) as contract
 ) captured;
 if actual is distinct from $expected${"functions":[{"acl":[["postgres","anon","EXECUTE",false],["postgres","authenticated","EXECUTE",false],["postgres","postgres","EXECUTE",false],["postgres","service_role","EXECUTE",false]],"config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.create_production_rework(p_job_id uuid, p_reason_category text, p_scope_details text, p_intake_date date, p_created_by text DEFAULT NULL::text)\n RETURNS production_rework_cycles\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare\n  target_job public.jobs%rowtype;\n  next_sequence integer;\n  created_cycle public.production_rework_cycles%rowtype;\nbegin\n  if p_reason_category not in ('quality_qc', 'shipping_handling', 'customer_change', 'other') then\n    raise exception using errcode = 'P0001', message = 'production_rework_validation', detail = '{\"message\":\"Choose a valid Rework reason.\"}';\n  end if;\n  if btrim(coalesce(p_scope_details, '')) = '' then\n    raise exception using errcode = 'P0001', message = 'production_rework_validation', detail = '{\"message\":\"Rework Scope / Work Required is required.\"}';\n  end if;\n  if p_intake_date is null then\n    raise exception using errcode = 'P0001', message = 'production_rework_validation', detail = '{\"message\":\"Intake / Return Date is required.\"}';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(p_job_id::text, 0));\n  select * into target_job from public.jobs where id = p_job_id for update;\n  if not found then raise exception 'Production Job not found.' using errcode = 'P0002'; end if;\n  if target_job.archived_at is not null then raise exception 'Archived Production Jobs cannot start Rework.' using errcode = 'P0001'; end if;\n  if target_job.production_status <> 'complete' then\n    raise exception 'Only a completed Production Job can start Rework.' using errcode = 'P0001';\n  end if;\n  if exists (select 1 from public.production_rework_cycles where job_id = p_job_id and production_status not in ('complete', 'cancelled')) then\n    raise exception 'This Production Job already has an active Rework cycle.' using errcode = '23505';\n  end if;\n\n  select coalesce(max(sequence_number), 0) + 1 into next_sequence\n  from public.production_rework_cycles where job_id = p_job_id;\n\n  insert into public.production_rework_cycles(job_id, sequence_number, reason_category, scope_details, intake_date, created_by)\n  values (p_job_id, next_sequence, p_reason_category, btrim(p_scope_details), p_intake_date, nullif(btrim(coalesce(p_created_by, '')), ''))\n  returning * into created_cycle;\n\n  insert into public.job_activity(job_id, event_type, summary, actor_name, metadata)\n  values (p_job_id, 'production_rework_created', format('Rework #%s created', next_sequence), nullif(btrim(coalesce(p_created_by, '')), ''),\n    jsonb_build_object('rework_cycle_id', created_cycle.id, 'sequence_number', next_sequence, 'reason_category', p_reason_category, 'intake_date', p_intake_date));\n  return created_cycle;\nend;\n$function$\n","owner":"postgres","signature":"create_production_rework(uuid,text,text,date,text)"},{"acl":[["postgres","anon","EXECUTE",false],["postgres","authenticated","EXECUTE",false],["postgres","postgres","EXECUTE",false],["postgres","service_role","EXECUTE",false]],"config":["search_path=public, pg_temp"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.save_production_planning_schedule_batch(p_job_proposals jsonb, p_phase_proposals jsonb, p_changed_by text, p_change_note text, p_batch_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare\n  actor text := nullif(trim(p_changed_by), '');\n  normalized_note text := nullif(trim(p_change_note), '');\n  normalized_phases jsonb := '[]'::jsonb;\n  request_payload jsonb;\n  prior_batch public.production_planning_schedule_batches%rowtype;\n  proposal jsonb;\n  proposal_index integer := 0;\n  phase_id uuid;\n  original_start date;\n  original_end date;\n  proposed_start date;\n  proposed_end date;\n  original_updated_at timestamptz;\n  change_source text;\n  conflicts jsonb;\n  phase_result jsonb := '[]'::jsonb;\n  job_result jsonb;\n  current_phase public.planning_phases%rowtype;\n  updated_phase public.planning_phases%rowtype;\n  final_result jsonb;\nbegin\n  if p_batch_id is null or actor is null then\n    raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n      detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'batch_id and changed_by are required')::text;\n  end if;\n  if coalesce(jsonb_typeof(p_job_proposals), '') <> 'array'\n    or coalesce(jsonb_typeof(p_phase_proposals), '') <> 'array'\n    or (jsonb_array_length(p_job_proposals) = 0 and jsonb_array_length(p_phase_proposals) = 0)\n  then\n    raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n      detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'at least one job or Phase proposal is required')::text;\n  end if;\n\n  for proposal in select value from jsonb_array_elements(p_phase_proposals)\n  loop\n    proposal_index := proposal_index + 1;\n    begin\n      phase_id := (proposal->>'phase_id')::uuid;\n      original_start := (proposal->>'original_start_date')::date;\n      original_end := (proposal->>'original_end_date')::date;\n      proposed_start := (proposal->>'proposed_start_date')::date;\n      proposed_end := (proposal->>'proposed_end_date')::date;\n      original_updated_at := (proposal->>'original_updated_at')::timestamptz;\n    exception when others then\n      raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n        detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'Phase proposal contains an invalid ID, date, or timestamp', 'proposal_index', proposal_index)::text;\n    end;\n    if proposed_end < proposed_start then\n      raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n        detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'Phase dates must form a valid inclusive interval', 'proposal_index', proposal_index)::text;\n    end if;\n    change_source := nullif(trim(proposal->>'change_source'), '');\n    if change_source not in ('planning_timeline', 'production_reschedule') then\n      raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n        detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'Phase change_source is invalid', 'proposal_index', proposal_index)::text;\n    end if;\n    normalized_phases := normalized_phases || jsonb_build_array(jsonb_build_object(\n      'phase_id', phase_id, 'original_start_date', original_start, 'original_end_date', original_end,\n      'original_updated_at', original_updated_at, 'proposed_start_date', proposed_start,\n      'proposed_end_date', proposed_end, 'change_source', change_source\n    ));\n  end loop;\n\n  if (select count(*) from (select element->>'phase_id' from jsonb_array_elements(normalized_phases) element group by 1) unique_phases)\n    <> jsonb_array_length(normalized_phases)\n  then\n    raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n      detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'duplicate Phase IDs are not allowed')::text;\n  end if;\n\n  request_payload := jsonb_build_object('jobs', p_job_proposals, 'phases', normalized_phases);\n  perform pg_advisory_xact_lock(hashtextextended('production-planning:' || p_batch_id::text, 0));\n  select * into prior_batch from public.production_planning_schedule_batches where batch_id = p_batch_id;\n  if found then\n    if prior_batch.request_payload <> request_payload or prior_batch.changed_by <> actor\n      or prior_batch.change_note is distinct from normalized_note\n    then\n      raise exception using errcode = 'P0001', message = 'production_planning_schedule_batch_reused',\n        detail = jsonb_build_object('code', 'production_planning_schedule_batch_reused', 'message', 'batch_id was already used for another request')::text;\n    end if;\n    return prior_batch.result_payload || jsonb_build_object('replayed', true);\n  end if;\n\n  perform phase.id\n  from public.planning_phases phase\n  join (select (element->>'phase_id')::uuid phase_id from jsonb_array_elements(normalized_phases) element) requested\n    on requested.phase_id = phase.id\n  order by phase.id for update of phase;\n\n  if (select count(*) from public.planning_phases phase where phase.id in\n    (select (element->>'phase_id')::uuid from jsonb_array_elements(normalized_phases) element))\n    <> jsonb_array_length(normalized_phases)\n  then\n    raise exception using errcode = 'P0001', message = 'production_planning_schedule_validation',\n      detail = jsonb_build_object('code', 'production_planning_schedule_validation', 'message', 'one or more Planning Phases do not exist')::text;\n  end if;\n\n  select jsonb_agg(jsonb_build_object(\n    'phase_id', phase.id, 'job_id', phase.job_id, 'title', phase.title,\n    'expected', jsonb_build_object('start_date', expected.original_start, 'end_date', expected.original_end, 'updated_at', expected.original_updated_at),\n    'current', jsonb_build_object('start_date', phase.start_date, 'end_date', phase.end_date, 'updated_at', phase.updated_at),\n    'proposed', jsonb_build_object('start_date', expected.proposed_start, 'end_date', expected.proposed_end)\n  ) order by phase.id) into conflicts\n  from public.planning_phases phase\n  join (\n    select (element->>'phase_id')::uuid phase_id,\n      (element->>'original_start_date')::date original_start,\n      (element->>'original_end_date')::date original_end,\n      (element->>'original_updated_at')::timestamptz original_updated_at,\n      (element->>'proposed_start_date')::date proposed_start,\n      (element->>'proposed_end_date')::date proposed_end\n    from jsonb_array_elements(normalized_phases) element\n  ) expected on expected.phase_id = phase.id\n  where phase.start_date is distinct from expected.original_start\n    or phase.end_date is distinct from expected.original_end\n    or phase.updated_at is distinct from expected.original_updated_at;\n  if conflicts is not null then\n    raise exception using errcode = 'P0001', message = 'production_planning_schedule_conflict',\n      detail = jsonb_build_object('code', 'production_planning_schedule_conflict', 'conflicts', conflicts)::text;\n  end if;\n\n  if jsonb_array_length(p_job_proposals) > 0 then\n    job_result := public.save_production_schedule_batch(p_job_proposals, actor, normalized_note, p_batch_id);\n  else\n    job_result := jsonb_build_object('batch_id', p_batch_id, 'replayed', false, 'updated_count', 0, 'ignored_no_op_count', 0, 'updated_jobs', '[]'::jsonb);\n  end if;\n\n  for proposal in select value from jsonb_array_elements(normalized_phases) order by (value->>'phase_id')::uuid\n  loop\n    phase_id := (proposal->>'phase_id')::uuid;\n    select * into current_phase from public.planning_phases where id = phase_id;\n    proposed_start := (proposal->>'proposed_start_date')::date;\n    proposed_end := (proposal->>'proposed_end_date')::date;\n    if current_phase.start_date is not distinct from proposed_start and current_phase.end_date is not distinct from proposed_end then\n      continue;\n    end if;\n    update public.planning_phases\n    set start_date = proposed_start, end_date = proposed_end\n    where id = phase_id returning * into updated_phase;\n    insert into public.job_activity(job_id, event_type, summary, actor_name, metadata)\n    values(updated_phase.job_id, 'planning_phase_schedule_changed', 'Planning Phase schedule changed: ' || updated_phase.title, actor,\n      jsonb_build_object('batch_id', p_batch_id, 'change_note', normalized_note, 'change_source', proposal->>'change_source',\n        'phase_id', updated_phase.id,\n        'old_values', jsonb_build_object('start_date', current_phase.start_date, 'end_date', current_phase.end_date),\n        'new_values', jsonb_build_object('start_date', updated_phase.start_date, 'end_date', updated_phase.end_date)));\n    phase_result := phase_result || jsonb_build_array(to_jsonb(updated_phase));\n  end loop;\n\n  final_result := jsonb_build_object(\n    'batch_id', p_batch_id, 'replayed', false,\n    'updated_count', coalesce((job_result->>'updated_count')::integer, 0) + jsonb_array_length(phase_result),\n    'updated_jobs', coalesce(job_result->'updated_jobs', '[]'::jsonb),\n    'updated_phases', phase_result\n  );\n  insert into public.production_planning_schedule_batches(batch_id, request_payload, changed_by, change_note, result_payload)\n  values(p_batch_id, request_payload, actor, normalized_note, final_result);\n  return final_result;\nend;\n$function$\n","owner":"postgres","signature":"save_production_planning_schedule_batch(jsonb,jsonb,text,text,uuid)"},{"acl":[["postgres","anon","EXECUTE",false],["postgres","authenticated","EXECUTE",false],["postgres","postgres","EXECUTE",false],["postgres","service_role","EXECUTE",false]],"config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.save_production_rework_mixed_schedule_batch(p_job_proposals jsonb, p_phase_proposals jsonb, p_rework_proposals jsonb, p_changed_by text, p_change_note text DEFAULT NULL::text, p_batch_id uuid DEFAULT gen_random_uuid())\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare canonical_result jsonb; rework_result jsonb;\nbegin\n  if coalesce(jsonb_typeof(p_job_proposals), '') <> 'array'\n    or coalesce(jsonb_typeof(p_phase_proposals), '') <> 'array'\n    or coalesce(jsonb_typeof(p_rework_proposals), '') <> 'array'\n    or (jsonb_array_length(p_job_proposals) = 0 and jsonb_array_length(p_phase_proposals) = 0 and jsonb_array_length(p_rework_proposals) = 0)\n  then\n    raise exception 'At least one valid Production, Planning, or Rework proposal is required.' using errcode = '22023';\n  end if;\n  if jsonb_array_length(p_job_proposals) > 0 or jsonb_array_length(p_phase_proposals) > 0 then\n    canonical_result := public.save_production_planning_schedule_batch(p_job_proposals, p_phase_proposals, p_changed_by, p_change_note, p_batch_id);\n  else\n    canonical_result := jsonb_build_object('updated_count', 0, 'updated_jobs', '[]'::jsonb, 'updated_phases', '[]'::jsonb);\n  end if;\n  rework_result := public.save_production_rework_schedule_batch(p_rework_proposals, p_changed_by, p_change_note, p_batch_id);\n  return jsonb_build_object(\n    'batch_id', p_batch_id,\n    'updated_count', coalesce((canonical_result->>'updated_count')::integer, 0) + coalesce((rework_result->>'updated_count')::integer, 0),\n    'updated_jobs', coalesce(canonical_result->'updated_jobs', '[]'::jsonb),\n    'updated_phases', coalesce(canonical_result->'updated_phases', '[]'::jsonb),\n    'updated_reworks', coalesce(rework_result->'updated_reworks', '[]'::jsonb)\n  );\nend;\n$function$\n","owner":"postgres","signature":"save_production_rework_mixed_schedule_batch(jsonb,jsonb,jsonb,text,text,uuid)"},{"acl":[["postgres","anon","EXECUTE",false],["postgres","authenticated","EXECUTE",false],["postgres","postgres","EXECUTE",false],["postgres","service_role","EXECUTE",false]],"config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.save_production_rework_schedule_batch(p_proposals jsonb, p_changed_by text, p_change_note text DEFAULT NULL::text, p_batch_id uuid DEFAULT gen_random_uuid())\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare\n  actor text := nullif(btrim(p_changed_by), '');\n  normalized_note text := nullif(btrim(p_change_note), '');\n  request_payload jsonb;\n  prior_batch public.production_rework_schedule_batches%rowtype;\n  proposal jsonb;\n  current_cycle public.production_rework_cycles%rowtype;\n  updated_cycle public.production_rework_cycles%rowtype;\n  updated_rows jsonb := '[]'::jsonb;\n  updated_count integer := 0;\n  final_result jsonb;\nbegin\n  if p_batch_id is null or actor is null then\n    raise exception 'Rework schedule batch ID and changed-by name are required.' using errcode = '22023';\n  end if;\n  if coalesce(jsonb_typeof(p_proposals), '') <> 'array' then\n    raise exception 'Production Rework proposals must be an array.' using errcode = '22023';\n  end if;\n\n  request_payload := jsonb_build_object('reworks', p_proposals);\n  perform pg_advisory_xact_lock(hashtextextended('production-rework:' || p_batch_id::text, 0));\n  select * into prior_batch from public.production_rework_schedule_batches where batch_id = p_batch_id;\n  if found then\n    if prior_batch.request_payload <> request_payload or prior_batch.changed_by <> actor\n      or prior_batch.change_note is distinct from normalized_note\n    then\n      raise exception 'Rework schedule batch ID was already used for another request.' using errcode = 'P0001';\n    end if;\n    return prior_batch.result_payload || jsonb_build_object('replayed', true);\n  end if;\n\n  for proposal in select value from jsonb_array_elements(p_proposals) loop\n    select * into current_cycle from public.production_rework_cycles where id = (proposal->>'rework_cycle_id')::uuid for update;\n    if not found then raise exception 'Rework cycle not found.' using errcode = 'P0002'; end if;\n    if current_cycle.production_status in ('complete', 'cancelled') then\n      raise exception 'Completed or cancelled Rework history cannot be rescheduled.' using errcode = 'P0001';\n    end if;\n    if current_cycle.updated_at <> (proposal->>'original_updated_at')::timestamptz\n      or current_cycle.planned_start is distinct from nullif(proposal->>'original_planned_start', '')::date\n      or current_cycle.planned_end is distinct from nullif(proposal->>'original_planned_end', '')::date then\n      raise exception using errcode = 'P0001', message = 'production_rework_schedule_conflict', detail = jsonb_build_object('rework_cycle_id', current_cycle.id)::text;\n    end if;\n    if ((nullif(proposal->>'proposed_planned_start', '') is null) <> (nullif(proposal->>'proposed_planned_end', '') is null)) then raise exception 'Both Rework planned dates are required.' using errcode = '22023'; end if;\n    update public.production_rework_cycles set\n      planned_start = nullif(proposal->>'proposed_planned_start', '')::date,\n      planned_end = nullif(proposal->>'proposed_planned_end', '')::date\n    where id = current_cycle.id returning * into updated_cycle;\n    updated_count := updated_count + 1;\n    updated_rows := updated_rows || to_jsonb(updated_cycle);\n    insert into public.job_activity(job_id, event_type, summary, actor_name, metadata)\n    values (updated_cycle.job_id, 'production_rework_schedule_changed', format('Rework #%s schedule changed', updated_cycle.sequence_number), actor, jsonb_build_object('rework_cycle_id', updated_cycle.id, 'planned_start', updated_cycle.planned_start, 'planned_end', updated_cycle.planned_end, 'change_note', normalized_note, 'batch_id', p_batch_id));\n  end loop;\n  final_result := jsonb_build_object('batch_id', p_batch_id, 'replayed', false, 'updated_count', updated_count, 'updated_reworks', updated_rows);\n  insert into public.production_rework_schedule_batches(batch_id, request_payload, changed_by, change_note, result_payload)\n  values (p_batch_id, request_payload, actor, normalized_note, final_result);\n  return final_result;\nend;\n$function$\n","owner":"postgres","signature":"save_production_rework_schedule_batch(jsonb,text,text,uu